        "conjecture_holds": rank_value >= D and perm_circuit_size <= (n ** 1.5) ** D,
        "counterexample": "" if rank_value >= D and perm_circuit_size <= (n ** 1.5) ** D else f"Rank={rank_value}, Perm Circuit Size={perm_circuit_size}"
    }

if __name__ == "__main__":
